<script setup lang="ts">
import { reactive, ref } from 'vue'
import { Plus, Trash2, Wallet, ArrowDownLeft, ArrowUpRight } from 'lucide-vue-next'
import { state, metrics, addTransaction, removeItem } from '../lib/store'
import { brl, dateBR, todayLocal } from '../lib/format'
import type { TransactionType } from '../lib/types'
const showForm = ref(false)
const form = reactive({ description: '', kind: 'entrada' as TransactionType, amount: 0, date: todayLocal() })
function submit() { if (!form.description.trim() || form.amount <= 0 || !form.date) return; addTransaction({ ...form, description: form.description.trim(), amount: Number(form.amount) }); Object.assign(form, { description: '', kind: 'entrada', amount: 0, date: todayLocal() }); showForm.value = false }
function drop(id: string) { if (confirm('Excluir este lançamento?')) removeItem('transactions', id) }
</script>
<template><div class="view-enter"><div class="page-intro"><div><p class="eyebrow"><span class="eyebrow-line"></span> FLUXO DE CAIXA</p><h1>Financeiro</h1><p class="page-subtitle">Registre o que entrou e saiu. Valores de todo o histórico.</p></div><button class="btn btn-dark" @click="showForm = true"><Plus :size="17"/> Novo lançamento</button></div>
  <div class="finance-summary"><div class="surface finance-box"><span><ArrowDownLeft :size="16"/> Receitas</span><strong>{{ brl(metrics.income) }}</strong><small>Entradas registradas</small></div><div class="surface finance-box"><span><ArrowUpRight :size="16"/> Despesas</span><strong>{{ brl(metrics.expenses) }}</strong><small>Saídas registradas</small></div><div class="surface finance-box balance"><span><Wallet :size="16"/> Saldo</span><strong>{{ brl(metrics.balance) }}</strong><small>Entradas menos saídas</small></div></div>
  <div class="surface"><div class="list-toolbar"><h2>Movimentações</h2><span class="item-counter">{{ state.transactions.length }} registro(s)</span></div><div class="table-wrap"><table v-if="state.transactions.length" class="data-table"><thead><tr><th>DESCRIÇÃO</th><th>DATA</th><th>TIPO</th><th>VALOR</th><th>AÇÕES</th></tr></thead><tbody><tr v-for="transaction in state.transactions" :key="transaction.id"><td class="strong">{{ transaction.description }}</td><td>{{ dateBR(transaction.date) }}</td><td><span class="pill" :class="transaction.kind">{{ transaction.kind === 'entrada' ? 'Entrada' : 'Saída' }}</span></td><td class="strong" :class="transaction.kind === 'entrada' ? 'positive' : 'negative'">{{ transaction.kind === 'entrada' ? '+' : '−' }} {{ brl(transaction.amount) }}</td><td><button class="icon-button danger" :aria-label="`Excluir ${transaction.description}`" @click="drop(transaction.id)"><Trash2 :size="16" /></button></td></tr></tbody></table><div v-else class="empty"><Wallet :size="27"/><b>Nenhum lançamento por aqui</b><p>Acompanhe recebimentos, custos de ferramentas, domínios e outras despesas.</p><button class="btn btn-outline" @click="showForm = true">Registrar movimentação</button></div></div></div>
  <div v-if="showForm" class="modal-backdrop" @click.self="showForm = false"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="finance-title"><div class="modal-head"><h2 id="finance-title">Novo lançamento</h2><button class="icon-button" aria-label="Fechar" @click="showForm = false">✕</button></div><form @submit.prevent="submit"><div class="field"><label for="f-description">Descrição *</label><input id="f-description" v-model="form.description" required maxlength="150" autofocus placeholder="Ex.: Entrada do projeto de convite"/></div><div class="form-row"><div class="field"><label for="f-kind">Tipo</label><select id="f-kind" v-model="form.kind"><option value="entrada">Entrada</option><option value="saida">Saída</option></select></div><div class="field"><label for="f-amount">Valor (R$) *</label><input id="f-amount" v-model.number="form.amount" required type="number" min="0.01" step="0.01" /></div></div><div class="field"><label for="f-date">Data *</label><input id="f-date" v-model="form.date" type="date" required /></div><div class="modal-actions"><button type="button" class="btn btn-outline" @click="showForm = false">Cancelar</button><button type="submit" class="btn btn-dark">Salvar lançamento</button></div></form></div></div>
</div></template>
